const data = $input.first().json;
const hotels = data.hotels || [];
const startIndex = data.startIndex || 0;
const chatId = data.chatId;
const offersSearchUrl = data.offersSearchUrl;
const sessionId = data.sessionId || String(Date.now());
const total = hotels.length;

const batchHotels = hotels.slice(startIndex, startIndex + 3).map((hotel, i) => {
  const lat = hotel.latitude;
  const lon = hotel.longitude;
  const locationLabel = [hotel.city, hotel.country].filter(Boolean).join(', ') || hotel.name || 'Hotel location';
  const mapsQuery = (lat !== undefined && lon !== undefined && lat !== null && lon !== null)
    ? `${lat},${lon}`
    : encodeURIComponent(`${hotel.name || ''} ${hotel.city || ''}`.trim());
  const mapsUrl = `https://www.google.com/maps/search/?api=1&query=${mapsQuery}`;

  let nights = 1;
  const inDate = new Date(hotel.checkIn);
  const outDate = new Date(hotel.checkOut);
  if (!isNaN(inDate) && !isNaN(outDate)) {
    nights = Math.max(1, Math.round((outDate - inDate) / (1000 * 60 * 60 * 24)));
  }

  const roomPhotos = (hotel.roomPhotoUrls || [])
    .filter((url) => typeof url === 'string' && url.trim() !== '')
    .map((url) => ({ url, type: 'room' }));

  const hotelPhotos = [hotel.imageUrl, ...(hotel.hotelPhotoUrls || [])]
    .filter((url) => typeof url === 'string' && url.trim() !== '')
    .map((url) => ({ url, type: 'hotel' }));

  const photoUrls = [...roomPhotos, ...hotelPhotos];

  const cardPhotos = [hotelPhotos[0]?.url, roomPhotos[0]?.url, roomPhotos[1]?.url].filter(Boolean);

  return {
    hotel,
    index: startIndex + i,
    total,
    chatId,
    sessionId,
    locationLabel,
    mapsUrl,
    nights,
    photoUrls,
    cardPhotos,
  };
});

const hasNext = (startIndex + 3) < total;
const nextIndex = startIndex + 3;

return [{ json: { batchHotels, chatId, hasNext, nextIndex, total, startIndex, offersSearchUrl, sessionId } }];

