async function isUrlValid(url) {
  try {
    await this.helpers.httpRequest({ method: 'HEAD', url, timeout: 8000 });
    return true;
  } catch (err) {
    const status = err?.response?.status || err?.statusCode;
    if (status === 403 || status === 405) {
      try {
        await this.helpers.httpRequest({
          method: 'GET',
          url,
          headers: { Range: 'bytes=0-0' },
          timeout: 8000,
        });
        return true;
      } catch (err2) {
        return false;
      }
    }
    return false;
  }
}

const items = $input.all();
const allUrls = items.map(item => item.json.photo_url).filter(Boolean);

const checks = await Promise.all(
  allUrls.map(async (url) => ({ url, valid: await isUrlValid.call(this, url) }))
);
const urls = checks.filter((c) => c.valid).map((c) => c.url);

const chunkSize = 10;
const chunks = [];
for (let i = 0; i < urls.length; i += chunkSize) {
  chunks.push(urls.slice(i, i + chunkSize));
}

return chunks.map(chunk => {
  const out = {};
  for (let i = 0; i < chunkSize; i++) {
    out[`url${i + 1}`] = chunk[i];
  }
  out.realCount = chunk.length;
  return { json: out };
});

const hotels = query.hotels;

function isValidHotelsShape(hotels) {
  if (!hotels || typeof hotels !== 'object' || Array.isArray(hotels)) return false;
  return Object.values(hotels).every((h) => {
    if (!h || typeof h !== 'object' || Array.isArray(h)) return false;
    const hotelImagesOk =
      Array.isArray(h.hotelImages) && h.hotelImages.every((u) => typeof u === 'string');
    const roomsOk =
      h.rooms &&
      typeof h.rooms === 'object' &&
      !Array.isArray(h.rooms) &&
      Object.values(h.rooms).every(
        (arr) => Array.isArray(arr) && arr.every((u) => typeof u === 'string')
      );
    return hotelImagesOk && roomsOk;
  });
}

if (!isValidHotelsShape(hotels)) {
  return JSON.stringify({
    error:
      'Invalid input. Expected { "hotels": { "<hotelName>": { "hotelImages": ["url1", ...], "rooms": { "<roomName>": ["url1", ...] } } } }',
  });
}

async function isUrlValid(url) {
  try {
    await this.helpers.httpRequest({ method: 'HEAD', url, timeout: 8000 });
    return true;
  } catch (err) {
    const status = err?.response?.status || err?.statusCode;
    if (status === 403 || status === 405) {
      try {
        await this.helpers.httpRequest({
          method: 'GET',
          url,
          headers: { Range: 'bytes=0-0' },
          timeout: 8000,
        });
        return true;
      } catch (err2) {
        return false;
      }
    }
    return false;
  }
}

async function validateUrlList(urls) {
  const checks = await Promise.all(
    urls.map(async (url) => ({ url, valid: await isUrlValid.call(this, url) }))
  );
  const validUrls = checks.filter((c) => c.valid).map((c) => c.url);
  return {
    validUrls,
    validCount: validUrls.length,
    totalChecked: urls.length,
  };
}

const hotelNames = Object.keys(hotels);

const results = await Promise.all(
  hotelNames.map(async (hotelName) => {
    const { hotelImages, rooms } = hotels[hotelName];

    const hotelImagesResult = await validateUrlList.call(this, hotelImages);

    const roomNames = Object.keys(rooms);
    const roomResults = await Promise.all(
      roomNames.map(async (roomName) => {
        const result = await validateUrlList.call(this, rooms[roomName]);
        return { roomName, ...result };
      })
    );

    const roomsOutput = {};
    for (const r of roomResults) {
      roomsOutput[r.roomName] = {
        validUrls: r.validUrls,
        validCount: r.validCount,
        totalChecked: r.totalChecked,
      };
    }

    return {
      hotel: hotelName,
      hotelImages: hotelImagesResult,
      rooms: roomsOutput,
    };
  })
);

const output = {};
for (const r of results) {
  output[r.hotel] = {
    hotelImages: r.hotelImages,
    rooms: r.rooms,
  };
}

return JSON.stringify({ results: output });

parameters.description:
Call this tool to check which photo URLs are actually reachable before sending them to 
the user. Input must be an object of the form:

{ 
  "hotels": { 
    "<hotelName>": { 
      "hotelImages": ["https://...jpg", "https://...jpg"], 
      "rooms": { 
        "<roomType>": ["https://...jpg", "https://...jpg"] 
      } 
    } 
  } 
}

STRICT RULES:
- Every hotel's value MUST be an object with exactly two keys: "hotelImages" and "rooms". 
  Never pass a hotel's value as a plain array — this is invalid and will be rejected.
- The hotel name key must be the hotel's name ONLY (e.g. "ibis Schiphol Amsterdam Airport"). 
  Never append the room type, bed type, or any other suffix to the hotel name.
- The room type/name (e.g. "Double", "Room With 1 Double Bed") belongs INSIDE that hotel's 
  "rooms" object as its own key — never in the hotel name, never merged into hotelImages.
- This rule applies identically to every hotel in the request — if you are validating 
  multiple hotels in one call, each one must follow this same nested shape. Do not use 
  the old shape for some hotels and the new shape for others.

Example with two hotels in one call:
{
  "hotels": {
    "Heart Of Amsterdam": {
      "hotelImages": ["https://...a_116.jpg", "https://...l_008.jpg"],
      "rooms": {
        "Bed In 8-bed Mixed Dormitory Room": ["https://...ro_066.jpg", "https://...ro_067.jpg"]
      }
    },
    "ibis Schiphol Amsterdam Airport": {
      "hotelImages": ["https://...f_004.jpg", "https://...a_110.jpg"],
      "rooms": {
        "Double": ["https://...ro_010.jpg", "https://...ro_011.jpg"]
      }
    }
  }
}

Returns a JSON object of the form:

{ 
  "results": { 
    "<hotelName>": { 
      "hotelImages": { "validUrls": [...], "validCount": N, "totalChecked": N }, 
      "rooms": { 
        "<roomType>": { "validUrls": [...], "validCount": N, "totalChecked": N } 
      } 
    } 
  } 
}

