          },
          "rooms": {
            "type": "object",
            "description": "Map of room type/name (e.g. 'Room With 1 Double Bed') to that room's own photo URLs only (from roomStatic images for that specific roomId).",
            "additionalProperties": {
              "type": "array",
              "items": { "type": "string" }
            }
          }
        },
        "required": ["hotelImages", "rooms"]
      }
    }
  },
  "required": ["hotels"]
